select temp.*,
       COALESCE((select count(*) from note_click_record 
           where note_id = temp.id
            and create_time >= #{startTime}
            and create_time <= #{endTime}
       ), 0) as click_count
from (

) temp

     and temp.user_id = #{userId}
     and temp.category_id = #{categoryId}

        and (temp.title like concat('%', #{title}, '%') 
        or temp.markdown_content like concat('%', #{title}, '%')
        or temp.author_name like concat('%', #{title}, '%')
        or temp.tags like concat('%', #{title}, '%'))

     and temp.is_public = #{isPublic}
     and temp.public_section_id = #{publicSectionId}
     and temp.status = #{status}
     and temp.create_time >= #{startTime}
     and temp.create_time <= #{endTime}


    order by 

        click_count
        temp.word_count
        temp.word_count
        temp.title
        temp.create_time

    asc
    desc

