update note
user_id = #{userId}, category_id = #{categoryId}, title = #{title}, filename = #{filename}, markdown_content = #{markdownContent}, word_count = #{wordCount}, tags = #{tags}, is_public = #{isPublic}, public_section_id = #{publicSectionId}, status = #{status}, sort_order = #{sortOrder}, create_time = #{createTime}, update_time = #{updateTime},
where id = #{id}
